def funnel_counts(events: list[dict[str, str]]) -> dict[str, int]:
    page_views = []
    for event in events:
        if event["kind"] == "page_view": page_views.append(event)
    viewed = {event["customer"] for event in page_views}
    carted = {event["customer"] for event in events if event["kind"] == "add_to_cart"} & viewed
    purchased = {event["customer"] for event in events if event["kind"] == "purchase"} & carted
    return {"views": len(viewed), "carts": len(carted), "purchases": len(purchased)}


